// ---------- Changelog ----------

/** Appends one audit entry. `changelog.id` is `uuid primary key default gen_random_uuid()`
 *  (supabase/migrations/0001_init.sql), so the insert must NOT supply an id ΓÇö let the database's
 *  own default generate it, exactly like any other column with a working server-side default.
 *  Minting one here with `newId('log')` produced a `log-xxxxxxxx` string, which is not a uuid, so
 *  Postgres rejected every insert with `invalid input syntax for type uuid`. Because every write
 *  route saves its real data *before* calling this (see routes/library.ts), that mismatch made the
 *  audit-log write throw on every single change while the change itself had already succeeded ΓÇö
 *  a pure id-generation/schema mismatch, never anything wrong with the entry being logged. */
export async function appendChangeLog(entry: Omit<ChangeLogEntry, 'Id' | 'At'>) {
  const at = nowIso();
  const { error } = await supabaseAdmin.from('changelog').insert({
    at,
    who: entry.Who,
    action: entry.Action,
    collection: entry.Collection,
    object_id: entry.ObjectId,
    object_name: entry.ObjectName,
    before: entry.Before,
    after: entry.After,
  });
  if (error) throw error;
}

export async function listChangeLog(limit = 200): Promise<ChangeLogEntry[]> {
  const { data, error } = await supabaseAdmin.from('changelog').select('*').order('at', { ascending: false }).limit(limit);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({
    Id: r.id,
    At: r.at,
    Who: r.who,
    Action: r.action,
    Collection: r.collection,
    ObjectId: r.object_id,
    ObjectName: r.object_name,
    Before: r.before,
    After: r.after,
  }));
}

