import { beforeEach, describe, expect, it, vi } from 'vitest';

/* The changelog `id` column is `uuid primary key default gen_random_uuid()`
   (supabase/migrations/0001_init.sql). `appendChangeLog` used to mint its own id with
   `newId('log')` ΓÇö a `log-xxxxxxxx` string that is not a uuid ΓÇö so Postgres rejected *every*
   insert with `invalid input syntax for type uuid`. Because each write route saves its real data
   before logging (routes/library.ts), the change succeeded while its audit-log call threw. These
   tests mock the Supabase client module (the pattern email.test.ts uses) and pin the fix: no id in
   the payload, the rest of the row mapped exactly, and a failing insert still surfacing. */

// repo.ts also imports pgPool.ts, which throws at import time without DATABASE_URL and is used
// only by withBondLock (never by appendChangeLog) ΓÇö stub it so importing the real repo.ts needs no
// database.
vi.mock('./pgPool.js', () => ({ pgPool: {} }));

// vi.hoisted runs before the hoisted vi.mock factories, so the supabase mock can reference these
// spies and the tests can inspect what appendChangeLog sent.
const { insertMock, fromMock, supabaseAdmin } = vi.hoisted(() => {
  const insertMock = vi.fn();
  const fromMock = vi.fn(() => ({ insert: insertMock }));
  return { insertMock, fromMock, supabaseAdmin: { from: fromMock } };
});

vi.mock('./supabase.js', () => ({ supabaseAdmin }));

import { appendChangeLog } from './repo.js';

// A representative entry ΓÇö the exact shape routes/library.ts logs on a record create.
const entry = {
  Who: 'Mike',
  Action: 'create' as const,
  Collection: 'virtues',
  ObjectId: 'v-resolve',
  ObjectName: 'Resolve',
  Before: null,
  After: { Id: 'v-resolve', Name: 'Resolve', Tagline: 'Grit & Will' },
};

// The changelog columns from 0001_init.sql, minus `id` (the DB default supplies it).
const DECLARED_COLUMNS_MINUS_ID = [
  'after',
  'action',
  'at',
  'before',
  'collection',
  'object_id',
  'object_name',
  'who',
];

beforeEach(() => {
  vi.clearAllMocks();
  // from() must keep returning the insert spy after clearAllMocks resets its implementation.
  fromMock.mockImplementation(() => ({ insert: insertMock }));
  insertMock.mockResolvedValue({ error: null });
});

describe('appendChangeLog', () => {
  it('sends no id at all, letting gen_random_uuid() supply the uuid primary key', async () => {
    await appendChangeLog(entry);

    expect(fromMock).toHaveBeenCalledWith('changelog');
    expect(insertMock).toHaveBeenCalledTimes(1);
    const payload = insertMock.mock.calls[0][0];
    expect(payload).not.toHaveProperty('id');
    expect(Object.prototype.hasOwnProperty.call(payload, 'id')).toBe(false);
  });

  it('inserts exactly the declared columns, snake_cased and correctly mapped', async () => {
    await appendChangeLog(entry);

    const payload = insertMock.mock.calls[0][0];
    // Exact key set proves both "no id" and "no stray/renamed column" in one assertion.
    expect(Object.keys(payload).sort()).toEqual(DECLARED_COLUMNS_MINUS_ID);
    expect(payload).toEqual({
      at: expect.any(String),
      who: entry.Who,
      action: entry.Action,
      collection: entry.Collection,
      object_id: entry.ObjectId,
      object_name: entry.ObjectName,
      before: entry.Before,
      after: entry.After,
    });
  });

  it('propagates a rejected insert rather than swallowing it', async () => {
    const boom = new Error('connection terminated unexpectedly');
    insertMock.mockRejectedValueOnce(boom);

    await expect(appendChangeLog(entry)).rejects.toBe(boom);
  });

  it('propagates an insert that resolves with an error', async () => {
    const pgError = { message: 'invalid input syntax for type uuid', code: '22P02' };
    insertMock.mockResolvedValueOnce({ error: pgError });

    await expect(appendChangeLog(entry)).rejects.toBe(pgError);
  });
});

